        nums[j] = nums[j + 1];
        nums[j + 1] = temp;
        swapped = true;
      }
    }
  } while (swapped);

  // Convert the sorted list back to a string and return it.
  String result = '';
  for (int k = 0; k < nums.length; k++) {
    result += '$nums[k]';
