    final String tempResult = utf16.decode(tempPtr.address, (result.length + str.length) * 2);
    tempResult += encodedStr;

    // Free the previous buffers and update the result pointer
    calloc.free(resultPtr);
    resultPtr = tempPtr;
    result = tempResult;
    calloc.free(ptr);
  }

  // Return the concatenated string
  return result;
