double triangleArea(double a, double b, double c) {
  // Check if the sides form a valid triangle using Heron's formula.
  // The area is zero if any side is non-positive or if the sum of two sides is less than or equal to the third.

  final s = (a + b + c) / 2;

  // Calculate the semi-perimeter squared and check for validity
  final sSquared = s * s;
  final term1 = s - a;
  final term2 = s - b;
  final term3 = s - c;

  // To avoid floating point inaccuracies with very small numbers, we use a small epsilon
  const tolerance = 1e-7;

  if (term1 <= tolerance || term2 <= tolerance || term3 <= tolerance) {
    return 0.0; // Triangle not possible
  }

  // Heron's formula calculation
  final discriminant = sSquared - term1 * term2 * term3;

  // If the discriminant is negative due to precision issues, it means the triangle isn't valid
  if (discriminant < -tolerance) {
    return 0.0; // Triangle not possible
  }

  final sqrtDiscriminant = sqrt(discriminant);
  final result = sqrt(4 * term1 * term2 * term3 * sqrtDiscriminant) / 4;

  return result;
}
