  if (k == 0 || arr.isEmpty) return [];

  final n = arr.length;
  if (n < k) throw ArgumentError('k cannot be larger than the array length');

  var maxIndex = 0;
  for (var i = 1; i < k; i++) {
    if (arr[i] > arr[maxIndex]) {
      maxIndex = i;
    }
  }

  List<int> result = [arr[maxIndex]];
  int currentMaxIndex = maxIndex;

  for (int i = k; i < n; i++) {
    if (i - k >= 0 && arr[i] > arr[currentMaxIndex]) {
      currentMaxIndex = i;
    }

    // Move window one step to the right
    if ((i - k + 1) % k == 0) {
      result.add(arr[currentMaxIndex]);
    }
  }

  return result;
}
