void _quickSort(List<int> arr, int low, int high) {
  if (low < high) {
    int pi = _partition(arr, low, high);

    _quickSort(arr, low, pi - 1); // Before pivot
    _quickSort(arr, pi + 1, high); // After pivot
  }
}

int _partition(List<int> arr, int low, int high) {
  int pivot = arr[high]; // Select last element as pivot
  int i = low - 1;       // Index of smaller element

  for (int j = low; j <= high - 1; j++) {
    if (arr[j] < pivot) {
      i++;
      swap(arr, i, j);
    }
  }

  swap(arr, i + 1, high);
  return i + 1;
}

void swap(List<int> arr, int i, int j) {
  var temp = arr[i];
  arr[i] = arr[j];
  arr[j] = temp;
}
