import 'dart:core';

/// Converts a list of strings into a sorted list of integer sums,
/// where each sum represents the total ASCII value of all characters in the respective string.
List<int> sortedListSum(List<String> lst) {
  // If the input list is null or empty, return an empty list.
  if (lst == null || lst.isEmpty) {
    return [];
  }

  List<int> result = [];

  // Iterate through each string in the input list
  for (String s in lst) {
    int sum = 0;

    // Calculate the sum of ASCII values of all characters in the current string
    for (int i = 0; i < s.length; i++) {
      sum += s.codeUnitAt(i);
    }

    result.add(sum);
  }

  // Sort the resulting list of sums in ascending order
  result.sort();

  return result;
}
```

